 23	class DiscourseContextBadgeWidget extends WidgetType {
 24	  constructor(
 25	    private target: DiscourseLinkTarget,
 26	    private plugin: DiscourseGraphPlugin,
 27	  ) {
 28	    super();
 29	  }
 30	
 31	  /** Keyed on what the badge displays, so keystrokes elsewhere do not rebuild it. */
 32	  eq(other: DiscourseContextBadgeWidget): boolean {
 33	    return (
 34	      this.target.file.path === other.target.file.path &&
 35	      this.target.relationCount === other.target.relationCount &&
 36	      this.target.nodeType.id === other.target.nodeType.id &&
 37	      this.target.nodeType.name === other.target.nodeType.name
 38	    );
 39	  }
 40	
 41	  toDOM(): HTMLElement {
 42	    return createDiscourseContextBadge({
 43	      file: this.target.file,
 44	      nodeType: this.target.nodeType,
 45	      relationCount: this.target.relationCount,
 46	      onActivate: ({ file, anchor }) =>
 47	        openDiscourseContextPopover({
 48	          plugin: this.plugin,
 49	          file,
 50	          anchor,
 51	        }),
 52	    });
 53	  }
 54	
 55	  /**
 56	   * Updates in place so a popover anchored to this badge keeps a connected
 57	   * anchor; without this CM6 replaces the element on every count change.
 58	   */
 59	  updateDOM(dom: HTMLElement): boolean {
 60	    updateDiscourseContextBadge({
 61	      badge: dom,
 62	      nodeType: this.target.nodeType,
 63	      relationCount: this.target.relationCount,
 64	    });
 65	    return true;
 66	  }
 67	
 68	  /** True (the CM6 default) means the editor ignores the event, so our click handler runs. */
 69	  ignoreEvent(): boolean {
 70	    return true;
 71	  }
