 74	const buildBadgeDecorations = (
 75	  view: EditorView,
 76	  plugin: DiscourseGraphPlugin,
 77	): DecorationSet => {
 78	  if (!plugin.settings.showDiscourseContextOverlay) return Decoration.none;
 79	  // Source mode shows raw markdown; a badge there is noise.
 80	  if (!view.state.field(editorLivePreviewField, false)) return Decoration.none;
 81	
 82	  const sourcePath = view.state.field(editorInfoField, false)?.file?.path;
 83	  if (!sourcePath) return Decoration.none;
 84	
 85	  const widgets = [];
 86	
 87	  for (const { from, to } of view.visibleRanges) {
 88	    const text = view.state.doc.sliceString(from, to);
 89	    let match: RegExpExecArray | null;
 90	    INTERNAL_LINK_RE.lastIndex = 0;
 91	
 92	    while ((match = INTERNAL_LINK_RE.exec(text)) !== null) {
 93	      const checkPos = from + match.index - 1;
 94	      const isEmbed =
 95	        checkPos >= 0 &&
 96	        view.state.doc.sliceString(checkPos, checkPos + 1) === "!";
 97	      if (isEmbed) continue;
 98	
 99	      const target = resolveDiscourseLinkTarget({
100	        plugin,
101	        linktext: extractLinktext(match[0]),
102	        sourcePath,
103	      });
104	      if (!target) continue;
105	
106	      const matchEnd = from + match.index + match[0].length;
107	      widgets.push(
108	        Decoration.widget({
109	          widget: new DiscourseContextBadgeWidget(target, plugin),
110	          side: 1,
111	        }).range(matchEnd),
112	      );
113	    }
114	  }
115	
116	  return Decoration.set(widgets, true);
117	};
