119	export const createDiscourseContextOverlayExtension = (
120	  plugin: DiscourseGraphPlugin,
121	): ViewPlugin<PluginValue> =>
122	  ViewPlugin.fromClass(
123	    class {
124	      decorations: DecorationSet;
125	      private enabled: boolean;
126	      private indexVersion: number;
127	
128	      constructor(view: EditorView) {
129	        this.enabled = plugin.settings.showDiscourseContextOverlay;
130	        this.indexVersion = plugin.relationsIndex.getVersion();
131	        this.decorations = buildBadgeDecorations(view, plugin);
132	      }
133	
134	      update(update: ViewUpdate): void {
135	        // Setting and relation changes arrive as an empty transaction, which
136	        // changes neither doc nor viewport, so both need comparing explicitly.
137	        const enabled = plugin.settings.showDiscourseContextOverlay;
138	        const indexVersion = plugin.relationsIndex.getVersion();
139	        if (
140	          !update.docChanged &&
141	          !update.viewportChanged &&
142	          enabled === this.enabled &&
143	          indexVersion === this.indexVersion
144	        ) {
145	          return;
146	        }
147	        this.enabled = enabled;
148	        this.indexVersion = indexVersion;
149	        this.decorations = buildBadgeDecorations(update.view, plugin);
150	      }
151	    },
152	    {
153	      decorations: (v) => v.decorations,
154	    },
155	  );
  1	import { parseLinktext, type MarkdownPostProcessorContext } from "obsidian";
  2	import type DiscourseGraphPlugin from "~/index";
  3	import {
  4	  badgeTargetPath,
  5	  createDiscourseContextBadge,
  6	  updateDiscourseContextBadge,
  7	  DISCOURSE_CONTEXT_BADGE_CLASS,
  8	} from "~/components/discourseContextBadge";
