 46	/** Idempotent: Obsidian reuses rendered sections and re-runs post processors. */
 47	export const applyDiscourseContextBadges = ({
 48	  plugin,
 49	  el,
 50	  sourcePath,
 51	}: {
 52	  plugin: DiscourseGraphPlugin;
 53	  el: HTMLElement;
 54	  sourcePath: string;
 55	}): void => {
 56	  const links = el.querySelectorAll<HTMLAnchorElement>("a.internal-link");
 57	
 58	  for (const link of Array.from(links)) {
 59	    const linkSourcePath = resolveLinkSourcePath({ plugin, link, sourcePath });
 60	    if (!linkSourcePath) continue;
 61	    const existing = link.nextElementSibling?.hasClass(
 62	      DISCOURSE_CONTEXT_BADGE_CLASS,
 63	    )
 64	      ? (link.nextElementSibling as HTMLElement)
 65	      : null;
 66	
 67	    // data-href holds the link as written; href is resolved and URL-encoded.
 68	    const linktext =
 69	      link.getAttribute("data-href") ?? link.getAttribute("href");
 70	    if (!linktext) {
 71	      existing?.remove();
 72	      continue;
 73	    }
 74	
 75	    const target = resolveDiscourseLinkTarget({
 76	      plugin,
 77	      linktext,
 78	      sourcePath: linkSourcePath,
 79	    });
 80	    if (!target) {
 81	      existing?.remove();
 82	      continue;
 83	    }
 84	
 85	    // Updated rather than replaced when the target is unchanged: an open
 86	    // popover anchored to this badge would otherwise hold a detached element.
 87	    if (existing && badgeTargetPath(existing) === target.file.path) {
 88	      updateDiscourseContextBadge({
 89	        badge: existing,
 90	        nodeType: target.nodeType,
 91	        relationCount: target.relationCount,
 92	      });
 93	      continue;
 94	    }
 95	
 96	    const badge = createDiscourseContextBadge({
 97	      file: target.file,
 98	      nodeType: target.nodeType,
 99	      relationCount: target.relationCount,
100	      onActivate: ({ file, anchor }) =>
101	        openDiscourseContextPopover({
102	          plugin,
103	          file,
104	          anchor,
105	        }),
106	    });
107	
108	    existing?.remove();
109	    link.insertAdjacentElement("afterend", badge);
110	  }
111	};
