119	export const createDiscourseContextOverlayPostProcessor =
120	  (plugin: DiscourseGraphPlugin) =>
121	  (el: HTMLElement, ctx: MarkdownPostProcessorContext): void => {
122	    if (!plugin.settings.showDiscourseContextOverlay) return;
123	    if (!ctx.sourcePath) return;
124	    // Rendered sections arrive detached, so an attached one is the plugin's own
125	    // MarkdownRenderer.render inside a modal, where the popover cannot dismiss.
126	    if (el.closest(".modal-container")) return;
127	    applyDiscourseContextBadges({ plugin, el, sourcePath: ctx.sourcePath });
128	  };
