 11	const REFRESH_DEBOUNCE_MS = 300;
 12	
 13	/** Only a discourse node's own frontmatter can change what a badge shows. */
 14	const isDiscourseNodeFile = (
 15	  plugin: DiscourseGraphPlugin,
 16	  file: TFile,
 17	): boolean =>
 18	  !!getNodeTypeIdFromFrontmatter(
 19	    plugin.app.metadataCache.getFileCache(file)?.frontmatter,
 20	  );
