 22	/**
 23	 * Reading view is refreshed in place: rerender() blanks a pane that is not
 24	 * currently painting.
 25	 */
 26	export const refreshDiscourseContextOverlaySurfaces = (
 27	  plugin: DiscourseGraphPlugin,
 28	): void => {
 29	  refreshMarkdownEditors(plugin.app);
 30	  plugin.app.workspace.iterateAllLeaves((leaf) => {
 31	    if (!(leaf.view instanceof MarkdownView)) return;
 32	    const el = leaf.view.previewMode?.containerEl;
 33	    if (!el) return;
 34	    if (!plugin.settings.showDiscourseContextOverlay) {
 35	      removeDiscourseContextBadges(el);
 36	      return;
 37	    }
 38	    const sourcePath = leaf.view.file?.path;
 39	    if (!sourcePath) return;
 40	    applyDiscourseContextBadges({ plugin, el, sourcePath });
 41	  });
 42	};
 43	
 44	export const registerDiscourseContextOverlayRefresh = (
 45	  plugin: DiscourseGraphPlugin,
 46	): void => {
 47	  const refresh = debounce(
 48	    () => refreshDiscourseContextOverlaySurfaces(plugin),
 49	    REFRESH_DEBOUNCE_MS,
 50	    true,
 51	  );
 52	
 53	  plugin.register(plugin.relationsIndex.onChange(refresh));
 54	  // Files that were nodes must still trigger a refresh once they stop being
 55	  // one, or their existing badges never get removed.
 56	  const knownNodePaths = new Set<string>();
 57	  // Seeded once the metadata cache is warm: a node that already existed at
 58	  // load is otherwise untracked, so its first change would skip the refresh.
 59	  plugin.app.workspace.onLayoutReady(() => {
 60	    const queryEngine = new QueryEngine(plugin.app);
 61	    for (const file of queryEngine.getFilesWithNodeTypeId()) {
 62	      knownNodePaths.add(file.path);
 63	    }
 64	  });
 65	  // "changed", not "resolved": resolved also fires while a preview renders.
 66	  plugin.registerEvent(
 67	    plugin.app.metadataCache.on("changed", (file) => {
 68	      if (isDiscourseNodeFile(plugin, file)) {
 69	        knownNodePaths.add(file.path);
 70	      } else if (!knownNodePaths.delete(file.path)) {
 71	        return;
 72	      }
 73	      refresh();
 74	    }),
 75	  );
 76	};

